dirent.h:
/* Runtime library, ABI v1, MIPS and RISC-V: <dirent.h>. opendir, readdir and closedir, which list a folder one entry at
   a time over the getdents call: "." and ".." first, then its files and folders. */
#ifndef _DIRENT_H
#define _DIRENT_H

#if !defined(__mips__) && !defined(__riscv)
#error "This <dirent.h> is the MIPS and RISC-V one, included in a compilation for another Target"
#endif

#include <sys/types.h>

#ifdef __cplusplus
extern "C" {
#endif

/* One entry of a folder, as readdir gives it. */
struct dirent {
	ino_t d_ino;              /* The entry's number, the one stat gives in st_ino. */
	off_t d_off;
	unsigned short d_reclen;
	unsigned char d_type;     /* What it is: DT_DIR or DT_REG. */
	char d_name[256];         /* Its name, ending with a NUL. */
};

/* d_type: what an entry is. */
#define DT_UNKNOWN 0
#define DT_FIFO    1
#define DT_CHR     2
#define DT_DIR     4  /* A folder. */
#define DT_BLK     6
#define DT_REG     8  /* A file. */
#define DT_LNK     10
#define DT_SOCK    12

/* A folder being read, which opendir returns and the other functions take. */
typedef struct __dirstream DIR;

/** Opens the folder at path for readdir; returns a DIR, or NULL with errno set (ENOENT, or ENOTDIR for a file). */
DIR *opendir(const char *path);
/** The folder's next entry, "." and ".." first; NULL at the end, with errno unchanged, or NULL with errno set on a failure. */
struct dirent *readdir(DIR *dir);
/** Closes a folder opendir opened and frees it; returns 0. */
int closedir(DIR *dir);

#ifdef __cplusplus
}
#endif

#endif

stdio.h:
/* Runtime library, ABI v1, MIPS and RISC-V: <stdio.h>. The Runtime library's <stdio.h>, which it includes first, and
   rename and remove, which the folder calls make possible. */
#ifndef _AED_POSIX_STDIO_H
#define _AED_POSIX_STDIO_H

#if !defined(__mips__) && !defined(__riscv)
#error "This <stdio.h> is the MIPS and RISC-V one, included in a compilation for another Target"
#endif

#include_next <stdio.h>

#ifdef __cplusplus
extern "C" {
#endif

/** Renames or moves the file at from to the path to, whose folder must exist; returns 0, or -1 with errno set: EEXIST when a file is already at to, EISDIR when from is a folder. */
int rename(const char *from, const char *to);
/** Deletes the file at path, or the folder at path when it is empty; returns 0, or -1 with errno set. */
int remove(const char *path);

#ifdef __cplusplus
}

extern "C++" {
namespace std {
using ::rename; using ::remove;
}
}
#endif

#endif

sys/stat.h:
/* Runtime library, ABI v1, MIPS and RISC-V: <sys/stat.h>. stat, which describes what is at a path, mkdir, which makes
   a folder, and the macros that read st_mode. struct stat is laid out as Linux lays out the structure its stat call
   fills: struct stat64 on MIPS and RV32, each in its own arrangement, and struct stat on RV64. Only st_mode, st_size,
   st_ino and st_nlink carry anything; the times, the owners and the rest read 0. */
#ifndef _SYS_STAT_H
#define _SYS_STAT_H

#if !defined(__mips__) && !defined(__riscv)
#error "This <sys/stat.h> is the MIPS and RISC-V one, included in a compilation for another Target"
#endif

#include <sys/types.h>

#ifdef __cplusplus
extern "C" {
#endif

#if defined(__mips__)
/* Linux's struct stat64 for MIPS o32 (arch/mips/include/uapi/asm/stat.h), 104 bytes. */
struct stat {
	unsigned long st_dev;
	unsigned long __st_pad0[3];
	ino_t st_ino;           /* The entry's number, the same for the whole run. */
	mode_t st_mode;         /* What it is (S_ISDIR, S_ISREG) and its permissions. */
	nlink_t st_nlink;       /* How many names it has: 1. */
	uid_t st_uid;
	gid_t st_gid;
	unsigned long st_rdev;
	unsigned long __st_pad1[3];
	off_t st_size;          /* A file's length in bytes; 0 for a folder. */
	long st_atime;
	unsigned long st_atime_nsec;
	long st_mtime;
	unsigned long st_mtime_nsec;
	long st_ctime;
	unsigned long st_ctime_nsec;
	unsigned long st_blksize;
	unsigned long __st_pad2;
	blkcnt_t st_blocks;
};
#else
/* Linux's generic struct stat64 on RV32 and struct stat on RV64 (include/uapi/asm-generic/stat.h): 104 and 128
   bytes, the same up to the times, which are 32-bit on RV32 and 64-bit on RV64. */
struct stat {
	unsigned long long st_dev;
	ino_t st_ino;           /* The entry's number, the same for the whole run. */
	mode_t st_mode;         /* What it is (S_ISDIR, S_ISREG) and its permissions. */
	nlink_t st_nlink;       /* How many names it has: 1. */
	uid_t st_uid;
	gid_t st_gid;
	unsigned long long st_rdev;
	unsigned long long __st_pad1;
	off_t st_size;          /* A file's length in bytes; 0 for a folder. */
	int st_blksize;
	int __st_pad2;
	blkcnt_t st_blocks;
	long st_atime;
	unsigned long st_atime_nsec;
	long st_mtime;
	unsigned long st_mtime_nsec;
	long st_ctime;
	unsigned long st_ctime_nsec;
	unsigned int __st_unused4;
	unsigned int __st_unused5;
};
#endif

/* st_mode: what an entry is, in the bits S_IFMT selects, */
#define S_IFMT   0170000
#define S_IFDIR  0040000
#define S_IFREG  0100000
#define S_IFCHR  0020000
#define S_IFBLK  0060000
#define S_IFIFO  0010000
#define S_IFLNK  0120000
#define S_IFSOCK 0140000
/* and the questions to ask of it. */
#define S_ISDIR(mode)  (((mode) & S_IFMT) == S_IFDIR)
#define S_ISREG(mode)  (((mode) & S_IFMT) == S_IFREG)
#define S_ISCHR(mode)  (((mode) & S_IFMT) == S_IFCHR)
#define S_ISBLK(mode)  (((mode) & S_IFMT) == S_IFBLK)
#define S_ISFIFO(mode) (((mode) & S_IFMT) == S_IFIFO)
#define S_ISLNK(mode)  (((mode) & S_IFMT) == S_IFLNK)
#define S_ISSOCK(mode) (((mode) & S_IFMT) == S_IFSOCK)

/* The permission bits, which every entry has all of. */
#define S_IRWXU 0700
#define S_IRUSR 0400
#define S_IWUSR 0200
#define S_IXUSR 0100
#define S_IRWXG 0070
#define S_IRGRP 0040
#define S_IWGRP 0020
#define S_IXGRP 0010
#define S_IRWXO 0007
#define S_IROTH 0004
#define S_IWOTH 0002
#define S_IXOTH 0001

/** Describes what is at path in *buf: its kind and permissions in st_mode, a file's size in st_size; returns 0, or -1 with errno set (ENOENT when nothing is there). */
int stat(const char *path, struct stat *buf);
/** Makes a folder at path, whose own folder must exist, ignoring mode; returns 0, or -1 with errno set (EEXIST when something is there already). */
int mkdir(const char *path, mode_t mode);

#ifdef __cplusplus
}
#endif

#endif

sys/types.h:
/* Runtime library, ABI v1, MIPS and RISC-V: <sys/types.h>, the types of the POSIX file and folder calls. Their sizes
   are musl's: off_t and ino_t are 64-bit on every Target. */
#ifndef _SYS_TYPES_H
#define _SYS_TYPES_H

#if !defined(__mips__) && !defined(__riscv)
#error "This <sys/types.h> is the MIPS and RISC-V one, included in a compilation for another Target"
#endif

typedef __SIZE_TYPE__ size_t;
typedef long ssize_t;
typedef long long off_t;
typedef unsigned long long ino_t;
typedef unsigned long long dev_t;
typedef unsigned int mode_t;
typedef unsigned int nlink_t;
typedef unsigned int uid_t;
typedef unsigned int gid_t;
typedef long blksize_t;
typedef long long blkcnt_t;

#endif

unistd.h:
/* Runtime library, ABI v1, MIPS and RISC-V: <unistd.h>. unlink and rmdir, which delete a file and an empty folder,
   and the numbers of the standard descriptors. */
#ifndef _UNISTD_H
#define _UNISTD_H

#if !defined(__mips__) && !defined(__riscv)
#error "This <unistd.h> is the MIPS and RISC-V one, included in a compilation for another Target"
#endif

#include <sys/types.h>

#ifdef __cplusplus
extern "C" {
#endif

#define STDIN_FILENO  0
#define STDOUT_FILENO 1
#define STDERR_FILENO 2

/** Deletes the file at path; returns 0, or -1 with errno set (EISDIR for a folder, which rmdir deletes). */
int unlink(const char *path);
/** Deletes the folder at path when it is empty; returns 0, or -1 with errno set (ENOTEMPTY when it holds anything). */
int rmdir(const char *path);

#ifdef __cplusplus
}
#endif

#endif
